function tree(color){if(color==='Purple')return EMPIRE_EDICTS;const start={Green:0,Red:9,Blue:18}[color];return EDICTS.slice(start,start+9);}
function migrate(color,levels){if(color!=='Purple'||!Object.keys(levels||{}).some(n=>Number(n)>=10&&Number(n)<=18))return {...levels};const out={},mapping={10:29,11:28,12:31,13:33,14:30,15:32,16:35,17:32,18:34};for(const [n,v] of Object.entries(levels||{})){const key=mapping[n]||n;out[key]=Math.max(out[key]||0,Math.max(0,Math.min(3,v)));}return out;}
function initial(color){const r={};for(const e of tree(color).slice(0,2))r[e.n]=1;return r;}
function bonuses(color,levels){levels=migrate(color,levels);const b={};for(const e of tree(color))for(let i=0;i<Math.min(3,levels[e.n]||0);i++){const row=e.levels[i];if(row.id<5)b[row.id]=Math.max(b[row.id]||0,row.value);else b[row.id]=row.value;for(const [type,value] of Object.entries(row.upgrades||{}))b[type]=Math.max(b[type]||0,value);}return b;}
// Match progress by the purpose of each edict, rather than importing another
