(function(root){const data={"Green":[{"caption":"兵临城下","intro":"西方群岛上的韦斯塔利亚公国曾远离大陆的纷争。如今，战火已来到城门前。"},{"caption":"乱世烽火","intro":"赤焰部落虽早已被帝国征服，却从未真正屈服。里瓦迪斯陷入混乱，部落趁机夺取我们的土地。"},{"caption":"迅疾突击","intro":"我们以神圣之名讨伐邪恶。西港城防坚固，正面进攻难以奏效；先用有限兵力建立大陆上的前进据点。"},{"caption":"新的对手","intro":"切断西港与帝都之间的联系。侦察兵发现北方叛军正在此地施展禁忌魔法，必须连同死灵法师一起消灭。"},{"caption":"西港攻防战","intro":"大陆上的军团正陷入两线作战，赤焰部落也加入了混战。攻占西港，确保援军能够顺利抵达。"},{"caption":"捍卫疆土","intro":"赤焰部落仍威胁着西部海岸。将他们逐出我们的土地，守住王国的边境。"},{"caption":"战场风云","intro":"进攻帝都前，先完成左翼包抄。死灵军团与北方教团正在雪地交战，趁机一举击败双方。"},{"caption":"帝国万岁","intro":"清除盘踞里瓦迪斯的死灵法师，让帝国重获新生。让新的皇帝和新的王旗在帝都崛起。"}],"Red":[{"caption":"战斗尚未结束","intro":"部落曾战败并蒙羞退却。新的可汗将带领勇士重新赢得胜利，向对手讨回血债。"},{"caption":"复仇之战","intro":"先知预见了伟大的胜利。韦斯塔利亚人无法再躲在厚重城墙之后，攻破他们的城镇与神殿。"},{"caption":"向东进军","intro":"东方的土地曾是祖先的故乡。不能任由帝国继续占据，夺回属于部落的家园。"},{"caption":"征服亡灵","intro":"死灵法师在东部海角建立了魔法实验室。赶在北方巫师之前夺取这些据点。"},{"caption":"各个击破","intro":"残余亡灵逃进了北方巫师的领地。用萨满新掌握的力量击败疲惫的北方军团。"},{"caption":"富饶北境","intro":"北方埋藏着丰富的财富。占领教团的矿场，为部落的发展取得金币与宝石。"},{"caption":"黑暗秘术","intro":"萨满掌握了帝国死灵法师的秘密，祖先已经重返战场。消灭帝国，让这份力量归于部落。"},{"caption":"部落复兴","intro":"帝国的都城近在眼前。终结长久以来的压迫，让伟大的可汗统治这片土地。"}],"Blue":[{"caption":"世界边缘","intro":"帝国奴役我们，教会迫害巫师，部落掠夺城镇。曾经的反抗因经验不足而失败，如今教团已变得更强。"},{"caption":"帝国末日","intro":"帝都传来警报：可汗与萨满已被死灵魔法腐蚀，他们献祭敌人并将其复活。清除故土上的帝国残军。"},{"caption":"敌友难辨","intro":"韦斯塔利亚本可成为盟友，但狂热的圣殿骑士阻止使者见到大公。他们仇恨我们的魔法，只能为自由而战。"},{"caption":"亡灵瘟疫","intro":"帝都传来噩耗：亡灵正在走出城门，复生的部落战士反抗自己的主人。阻止他们越过边境。"},{"caption":"光与魔法","intro":"我们终于与韦斯塔利亚结盟。教团向东推进，王国从南方进攻；帝都外围的军队已经疲惫，必须迅速支援。"},{"caption":"净化之战","intro":"无人应随意操纵黑暗。部落萨满低估了死灵魔法，瘟疫正在从内部吞噬部落。结束这场灾难。"},{"caption":"完成包围","intro":"联盟之外的领地仍遍布亡灵。与韦斯塔利亚军队协同作战，完成对帝都的包围。"},{"caption":"最终决战","intro":"我们将再次与韦斯塔利亚人在战场相遇，这一次是并肩作战。让神圣之光与北方魔法共同驱散亡灵。"}]};if(typeof module!=="undefined")module.exports=data;else root.NativeLevelInfo=data;})(typeof window!=="undefined"?window:globalThis);

