function order(p,h,fromBadge=false){badgeLayoutCache=null;if(!unitIds.size)return;const ids=[...unitIds];if(!ids.length){toast('请按住城堡上方的兵种圆圈，拖到目的地出征');return;}let target=h&&(h.type==='building'?battle.building(h.id):h.type==='unit'?battle.unit(h.id):h.type==='chest'?battle.chest(h.id):null);if(target?.garrisonId)target=battle.building(target.garrisonId);else if(target&&target.owner===player&&!('queue' in target)){const castle=battle.buildings.filter(b=>battle.canEnter(b,player)&&(buildingContains(b,p)||dist(b,p)<52)).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(castle)target=castle;}let point=target||p;if(!target&&(battle.data.roads?.edges.length?dist(point,battle.projectRoad(point))>24:!battle.walkable(Math.floor(point.x/10),Math.floor(point.y/10)))){toast('部队只能沿道路行军，请选择道路或城池');return;}if(!target&&battle.data.roads?.edges.length)point=battle.projectRoad(point);battle.command(ids,point,target?.id);commandMarker={x:point.x,y:point.y,art:target&&'queue' in target?(battle.canEnter(target,player)?'enter':'attack'):commandArt(h),battle,until:battle.time+1.3};NativeAudio.play(battle.unit(ids[0])?.type==='siege'?'sndSendSiege':battle.unit(ids[0])?.type==='cavalry'?'sndSendHorses':'sndSendSoldiers');toast(target?.ruined&&battle.canEnter(target,player)?'进入废墟开始修复，敌人接近时驻军会出战' :target&&target.owner!==player?'进攻目标！':target&&'queue' in target?'进入己方城堡驻扎修复':'部队开始行军');}
