applyOriginalButtons();reset();showTitle();function frame(now){const dt=Math.max(0,(now-last)/1000);last=now;if(window.Network?.active)Network.render();if(active()&&!paused){if(!window.Network?.active)localClock.advance(dt,speed,step=>{if(battle.result)return;localMotion.beforeStep(battle);battle.update(step);});if(battle.result&&!handledResult){if(window.Network?.active)Network.finish();else finish();}}else localClock.reset();NativeAudio.tick(battle,started&&!battle.result&&$('overlay').classList.contains('hidden'));if($('overlay').classList.contains('hidden'))draw();uiElapsed+=Math.min(dt,.25);if(uiElapsed>.18){warmBattleSprites();updateUI();uiElapsed=0;}requestAnimationFrame(frame);}requestAnimationFrame(frame);

