let badgeLayoutCache=null;
function badgePoint(u){
 if(!u.garrisonId)return{x:u.x,y:u.y-60};
 if(!badgeLayoutCache||badgeLayoutCache.battle!==battle||badgeLayoutCache.units!==battle.units||badgeLayoutCache.time!==battle.time||badgeLayoutCache.count!==battle.units.length){
  const buildings=new Map(battle.buildings.map(b=>[b.id,b])),groups=new Map(),points=new Map();
  for(const v of battle.units)if(v.garrisonId){if(!groups.has(v.garrisonId))groups.set(v.garrisonId,[]);groups.get(v.garrisonId).push(v);}
  for(const [id,group]of groups){const b=buildings.get(id);if(!b)continue;const y=BuildingUILayout.label(b,BuildingPivots,GAME_DATA.sprites).y,columns=Math.min(5,group.length);group.forEach((v,index)=>points.set(v.id,{x:b.x+(index%5-(columns-1)/2)*38,y:y-36-Math.floor(index/5)*40}));}
  badgeLayoutCache={battle,units:battle.units,time:battle.time,count:battle.units.length,points};
 }
 return badgeLayoutCache.points.get(u.id)||{x:u.x,y:u.y-60};
}
